quests[47018] = { id = 47018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Mastery: Rumblings Near Feltotem", description = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.\n\nThe drogbar chieftain, Navarrogg, is handling this personally and we'd like you to meet him near the Feltotem village.", completion = "Thank you for coming. I am glad you are treating this threat seriously.", objectives = "Find Navarrogg at the Misty Coast in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47019] = { id = 47019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windwalker: Rumblings Near Feltotem", description = "The Highmountain have passed along a dire warning from their drogbar allies. The Feltotem are spreading their demonic corruption into the wildlife around them, infecting the land itself. We believe this is something that should be looked into sooner rather than later.\n\nThe drogbar chieftain, Navarrogg, is handling this personally and we'd like you to meet him near the Feltotem village.", completion = "Thank you for coming. I am glad you are treating this threat seriously.", objectives = "Find Navarrogg at the Misty Coast in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
