quests[47022] = { id = 47022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protection: Aid of the Illidari", description = "Thankfully, we are not quite alone in uncovering the Legion's plots to infiltrate the city.\n\nKor'vas Bloodthorn of the Illidari has taken to patrolling the city streets on her own to find the source behind the recent attacks.\n\nI do not entirely trust these 'demon hunters', but they have at least proved adept at their namesake. I suggest you find her and see what she has uncovered before the Legion strikes once more.", completion = "You - I've seen you out on the isles.\n\nWe need to move quickly!", objectives = "Find Kor'vas Bloodthorn in the streets of Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
