quests[47039] = { id = 47039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marksmanship: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.", completion = "You come from the Kirin Tor? So you'll help me find my brother?", objectives = "Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47040] = { id = 47040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate Sealed", objectives = "I have bent this to my will, I have drained its power, and summoned a Seal. Would you like it?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47041] = { id = 47041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affliction: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.", completion = "You come from the Kirin Tor? So you'll help me find my brother?", objectives = "Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47042] = { id = 47042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow: The Twisted Twin", description = "I have a request from an old friend, Karam Magespear, to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him.\n\nOriginally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order.\n\nFind Karam in the Legerdemain Lounge and see if you can lend a hand.", completion = "You come from the Kirin Tor? So you'll help me find my brother?", objectives = "Meet with Karam Magespear at the Legerdemain Lounge in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47043] = { id = 47043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Havoc: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.", completion = "So someone stole the Focusing Iris and you suspect Xylem might be the culprit? You may be right. \n\nIt is no secret that the archmage has been seeking artifacts of late. However, after the discovery of an ancient grimoire in the Legashi ruins, Xylem has become... unstable. I fear the grimoire may be stealing his mind.\n\nI can help you gain audience with the archmage.  With any luck, you can reclaim the Iris peacefully.", objectives = "Travel to Xylem's Tower within Bear's Head in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47044] = { id = 47044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.2 Broken Shore - Buildings - Activation Buff - Nether Disruptor - Seal Your Fate - Day 2 - Tracking" }
quests[47045] = { id = 47045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Further Progress", objectives = "The Disruptor continues to bend to my will! I will be unstoppable!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47046] = { id = 47046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.", completion = "So someone stole the Focusing Iris and you suspect Xylem might be the culprit? You may be right. \n\nIt is no secret that the archmage has been seeking artifacts of late. However, after the discovery of an ancient grimoire in the Legashi ruins, Xylem has become... unstable. I fear the grimoire may be stealing his mind.\n\nI can help you gain audience with the archmage.  With any luck, you can reclaim the Iris peacefully.", objectives = "Travel to Xylem's Tower within Bear's Head in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47047] = { id = 47047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.", completion = "So someone stole the Focusing Iris and you suspect Xylem might be the culprit? You may be right. \n\nIt is no secret that the archmage has been seeking artifacts of late. However, after the discovery of an ancient grimoire in the Legashi ruins, Xylem has become... unstable. I fear the grimoire may be stealing his mind.\n\nI can help you gain audience with the archmage.  With any luck, you can reclaim the Iris peacefully.", objectives = "Travel to Xylem's Tower within Bear's Head in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47048] = { id = 47048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtlety: The Thieving Apprentice", description = "The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him.\n\nFortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem.\n\nI'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to.", completion = "So someone stole the Focusing Iris and you suspect Xylem might be the culprit? You may be right. \n\nIt is no secret that the archmage has been seeking artifacts of late. However, after the discovery of an ancient grimoire in the Legashi ruins, Xylem has become... unstable. I fear the grimoire may be stealing his mind.\n\nI can help you gain audience with the archmage.  With any luck, you can reclaim the Iris peacefully.", objectives = "Travel to Xylem's Tower within Bear's Head in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47049] = { id = 47049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonology: Fate of the Tideskorn", description = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion.\n\nIt complicates matters that this vrykul may in fact be Skovald's heir.\n\nTake the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start.", completion = "Yes, outsider? What business do you have here?", objectives = "Search Jandvik for the vrykul mentioned in the scrolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
