quests[47054] = { id = 47054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touched By Fate", objectives = "I am... spent. I fear I have gone too far. Here, take this final Seal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47055] = { id = 47055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire: The Folly of Levia Laurence", description = "Levia Laurence was once a member of the Kirin Tor. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good.\n\nLevia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous if her knowledge fell into their hands.\n\nShe was last seen at the Scribe's Sacellum. Ask around there and see if you can pick up her trail.", progress = "Have you found any clues to Levia's disappearance?", completion = "So it seems that Levia has fallen under the spell of a succubus' seduction. I fear her time alone as an outcast must have left her vulnerable to such tactics. I cannot help but feel some guilt for her turning down this path.\n\nIn any case, Levia is in great danger. She must be found!", objectives = "Ask around the city for information on Levia Laurence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
