quests[47066] = { id = 47066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consecrating Ground", description = "We have everything we need.\n\nIn the alcove below you will find the shattered remains of the Argunite Matrix. Replacing the Keystone will restore it to full capacity.\n\nThe pylons you activated will then be able to repel those who still hunt my people. At long last this battle will be over.\n\nI hope it brings them peace.", progress = "Hurry {name}, we cannot let this continue any longer.", completion = "<Velen peers at you, troubled.>", objectives = "Repair the Argunite Matrix beneath Triumvirate's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47067] = { id = 47067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Lost Knowledge", description = "During the assault, our forces uncovered an ancient night elf tome. The fact that it survived so long in these harsh lands is quite remarkable.\n\nIts enchantments have faded over the ages, but I sense the book is almost... hungry, as if reaching out to places where the night elves practiced magic long ago.\n\nBringing the tome to nearby ruins may reveal secrets that could give us an edge against the Legion.", progress = "How was the tour of night elf ruins?", completion = "This tome is fascinating! It appears to seek out any and all knowledge that it does not already possess.\n\nI'd wager an experienced researcher could direct it to locate specific knowledge.\n\nHmm, that gives me an idea...", objectives = "Use the tome at several night elf ruins on the Broken Shore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47068] = { id = 47068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rare Elite 25" }
quests[47069] = { id = 47069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivering Lost Knowledge", description = "The very nature of this ancient night elf tome causes the book to seek out knowledge. This could prove to be a serious boon to your efforts to research your artifact weapon.\n\nI'd wager the scholars in your order hall would find it of great use, possibly unlocking new avenues of empowerment.\n\nI suggest you take it to them immediately. We need every advantage possible against the Legion!", completion = "What have you brought today, Grandmaster?\n\n<Cho examines the ancient tome.>\n\nThis book... it changes everything!", objectives = "Speak with the artifact researcher in your class order hall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
