quests[47179] = { id = 47179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tier 3 Mob Weekly Bonus" }
quests[47180] = { id = 47180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pulsing Madness", description = "This broken still retains some of his sanity, though not all of it.\n\nI can sense some Void influence nearby, but it is isolated to small pockets. Dispelling these manifestations should help our friend here clear his mind.\n\nPerhaps we can use the prayer fragments you found, as they still contain some Light energy.\n\nI will try and make sense of his chattering in the meantime. Maybe we can learn something about what is happening here.", completion = "I can feel the Void's influence retreating. Perhaps now we can find out what happened here.", objectives = "Dispel 5 Void Manifestations.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47181] = { id = 47181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smoking Gun", description = "The Ashvane Company doesn't know it yet, but throwing you into Tol Dagor was the biggest mistake they've ever made.\n\nThat new powder we swiped could be the key to bringing them down.\n\nFirst, how about we give everyone a little demonstration of just how powerful this stuff is?\n\n<Flynn loads a pinch of the glittering powder into his pistol.>\n\nGo ahead, take a shot at that barrel over there.", progress = "Don't worry, it won't hurt anyone.\n\nI think.", completion = "Adds a kick, don't it?", objectives = "Fire Flynn's Pistol at the Water Barrel in the Harbormaster's Office.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47182] = { id = 47182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Long Overdue", description = "I have learned much. High Inquisitor Raalgar has moved to a base near the Legion citadel across the mountains. This is where he keeps the Fel Heart of Argus, the source of his immortality, and it is powered by wells leading directly to the core of Argus. \n\nHe is preparing to attack so you will strike first. Mark the location of the wells and I will rain holy fire upon them with the Vindicaar's guns. With that connection to the fel on Argus broken, Raalgar can be killed and the Fel Heart retrieved.", progress = "Have you dealt with High Inquisitor Raalgar yet?", completion = "You are a true hero, {name}. Even though the demons freed Raalgar and thought him immortal, he was no match for you! Perhaps the Fel Heart will be of use to you. It is now available in the Matrix Core.", objectives = "Mark the Argussian Heartwells for the Vindicaar's guns, kill the Legion garrison, and retrieve the Fel Heart of Argus from High Inquisitor Raalgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47183] = { id = 47183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkhaan's Plan", description = "Arkhaan remembers. He remembers something that will... yes... will save us.\n\nFollow Arkhaan. Isolon calls! We will offer soft words to the Light. The Light will banish the darkness.\n\n<Arkhaan eyes Alleria warily.>\n\nArkhaan will watch that one closely.", completion = "I should have seen this coming.", objectives = "Follow Arkhaan to Isolon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47184] = { id = 47184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkhaan's Peril", description = "Whatever called to him, it cannot have good intentions. We need to go in after him.\n\nBefore we step through this portal, {name}... ensure you are prepared to fight. The Void's influence is rarely peaceful.", progress = "We must address this threat.", completion = "As I said, the Void's influence is rarely peaceful. We must press on.", objectives = "Enter the Void Tear and deal with Arkhaan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47185] = { id = 47185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Boss Weekly Bonus" }
quests[47186] = { id = 47186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanctum of the Sages", description = "Sounds like you'll be working with us for awhile.\n\nCyrus will charter a naval transport between here and Stormwind, but I expect you'll want something a bit faster for day to day use.\n\nHead back upstairs and take a left when you get outside. You'll find an old study where the Tidesages used to conduct their magic rituals.\n\nSurely your Alliance mages have already sensed its power.\n\nInform them they may open their portals there. The harbor guards will keep the room secure.", progress = "The Tidesages abandoned that place months ago when they pulled back to their monasteries. We still don't know why.", completion = "All set?\n\nGood timing. I have your briefing ready.", objectives = "Speak with a 7th Legion Mage in the Sanctum of the Sages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47188] = { id = 47188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aid of the Loa", description = "De blood trolls are stronger than ever, thanks to dis G'huun... and now dey are empowering a giant construct!\n\nWe need a plan to destroy dat construct, G'huun, and de blood trolls. It is not going to be easy.\n\nBut I have an idea.", progress = "We have a lot to talk about.", completion = "Getting de loa's help may be de only chance we have at stopping de blood trolls. \n\nLet's get moving.", objectives = "Hold council with Talanji and Rokhan to decide your next steps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47189] = { id = 47189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Nation Divided", description = "Kul Tiras must be unified before it can be of any help to the Alliance.\n\nLet's get you briefed on the current situation in each of our major territories.\n\nThen you can take a look at the map behind me and make the call on where you want to go first.", progress = "Have you figured out your next move? Use the planning map to help you decide.", completion = "We'll support you however we can.", objectives = "Inspect the Scouting Map in the Harbormaster's Office.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47191] = { id = 47191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusion - Demonic Tyranny" }
quests[47193] = { id = 47193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azsuna" }
quests[47194] = { id = 47194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Highmountain" }
quests[47195] = { id = 47195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Stormheim" }
quests[47196] = { id = 47196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Val'sharah" }
quests[47198] = { id = 47198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Want Us Alive", description = "Blood troll poisons are made to paralyze, not kill. See, dey want us alive.\n\nI do not feel good thinking about why.\n\nI am making antitoxins as quickly as I can, but I need someone like yourself to get out dere and test dem. Take what I have made so far and see if we can get those soldiers back on their feet.", completion = "It worked? Good! I shall have some of de wounded help me craft more.", objectives = "Cure 8 Wounded Captives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47199] = { id = 47199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood Gate", description = "We just received word that the Northern border is under heavy attack by an army of blood trolls.\n\nKing Rastakhan has called for reinforcements.\n\nYou are more familiar with that threat than any of us. Go and do what you can to help them.", completion = "Welcome to de edge of my domain, in more ways than one.", objectives = "Journey to the Blood Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47200] = { id = 47200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ticks", description = "Kill those bloodbellies before dey take off with all of my soldiers! I will have my troops prepare for a flanking charge.", progress = "We are losing too many, too quickly.", completion = "At last, some breathing room. Now we must press our advantage.", objectives = "Slay 6 Bloodbelly Fliers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47201] = { id = 47201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rokhan", completion = "Ha! Thought I be singin' with Bwonsamdi soon. But no.", objectives = "Ride the Old Rotana into the fray and then find Rokhan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47202] = { id = 47202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Message", description = "The time has come for me to travel to the Broken Shore and see, for myself, the place where my father died.\n\nIf I am to be the king my father was... the king Stormwind deserves, I must know firsthand the threat my people face.\n\nPlease tell my advisors that I've gone to the Broken Shore. If I told them myself they'd only try and stop me.\n\nI'll wait for you at Deliverance Point. Farewell.", completion = "<Velen listens closely to your words as you tell him of King Anduin's plan.>\n\nThe Broken Shore is a dangerous place... far too dangerous to travel alone. But perhaps this journey is necessary for Anduin to find peace.\n\nWhen the moment is right, I'll inform King Greymane of Anduin's departure. Until then, go and see that Anduin is not alone on the Broken Shore. I trust that you will return him safely.", objectives = "Speak with Prophet Velen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47203] = { id = 47203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throwing Shade", description = "That was Locus-Walker. He taught me all that I know about the Void, and he still has more to teach me.\n\nIf he is here, then the ethereals' presence only intrigues me further. I had thought him the only one of his kind, but now that I have seen another tangling with the Void...\n\nCome, we must play his game if we want to learn what he knows. He appears to have gone toward the Umbra Hollows to the north.", progress = "Move quickly, or we may lose him.", completion = "<Alleria seems momentarily speechless.>", objectives = "Investigate the Umbra Hollows with Alleria and Locus-Walker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47204] = { id = 47204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The New Frontline", description = "Kill anything ya see dat not a Zandalari!", completion = "It may seem like a lot, but trust me when I say we saw a lot more comin' when on our way here.", objectives = "Slay Blood Troll forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47205] = { id = 47205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warmother", description = "Old Rotana be cursed by da warmother dese vile blood trolls brought with dem. We need to take her down so we can get dis old direhorn back in da field.", completion = "Dat vile creature took out half da scouts who came with me. Ya did good.", objectives = "Slay Warmother Shazraka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47207] = { id = 47207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
