quests[47214] = { id = 47214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47215] = { id = 47215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47217] = { id = 47217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sources of Darkness", description = "I think I understand what he was trying to show us, {name}.\n\nI feel a surge of power building ahead. They must be cultivating the Void, calling it here.\n\nWe need to stop them before they plunge this entire city into shadow. Find the source and cut it off by any means necessary.\n\nLocus-Walker and I have unfinished business to attend to.", progress = "Locus-Walker and I have some unfinished business to attend to.", completion = "We buy time but nothing more.", objectives = "Deactivate 5 Void Harvesters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47218] = { id = 47218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowguard Incursion", description = "As you have surely gathered by now, a certain subset of my people have tragically succumbed to the call of the Void.\n\nI had hoped to find more who possess the necessary strength of mind. I am disappointed to find such an utter lack of resistance.\n\nIt cannot be helped. To advance your cause, and mine, we will need to eradicate these weak-willed beings.", progress = "Walking the razor's edge does have risks, {name}.", completion = "It is good to know we can share a common goal. Perhaps I will find some use for your kind yet.", objectives = "Slay 15 Shadowguard Ethereals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47219] = { id = 47219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vessel Made Ready", description = "After some consideration, I have decided to allow Alleria another opportunity to pursue her destiny.\n\nI suppose you want to know what that means, mortal.\n\n<Locus-Walker laughs.>\n\nMeet us deep in the Shadowguard camp ahead- my brethren are preparing a summons that will provide adequate energy for Windrunner to begin again.\n\nWitness what happens when you harness the Void's power.", progress = "I see the path clearly, {name}.", completion = "<Alleria takes the heart in her hands.>\n\nThis is the next step, {name}. Thank you for bringing me to this point.", objectives = "Defeat Nhal'athoth and collect his heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47220] = { id = 47220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Beacon in the Dark", description = "That was... an intense experience.\n\n<Alleria rubs her forehead.>\n\nIt is difficult to focus. I need you to return to Velen. Give him this.\n\n<She places something cold and dense in your palm.>\n\nI feel as though he should have it, though I am not sure why.\n\nTell him all that we have learned. I am sure Romuul will have been watching our progress. With any luck, a beacon is already headed our way.", progress = "What is this? Such darkness...", completion = "What is it you bring, {name}?\n\n\n\nIntriguing...", objectives = "Take the Remnant of Nhal'athoth to Velen on the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47221] = { id = 47221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hand of Fate", completion = "I'm glad you were among those called for the expedition to Argus. There will be plenty of fighting ahead.", objectives = "Meet your escort to the Exodar at Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47222] = { id = 47222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two If By Sea", description = "The Tomb of Sargeras was only the beginning. If we do not destroy the Legion utterly, they will return even stronger.\n\nWe will travel to Azuremyst by sea to avoid drawing unnecessary attention. The less time the Legion has to react to our assault, the better.\n\nJust say the word when you are ready to depart.", completion = "May the Light protect us all this day.", objectives = "Speak to Vereesa Windrunner to set sail for the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47223] = { id = 47223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Exodus", description = "Prophet Velen and the others have gathered within the Vault of Lights below. There is an entrance just down this path.\n\nWe should find the Prophet at once so that we do not stall the invasion.", completion = "Thank the Light you have arrived.", objectives = "Meet Prophet Velen in the Vault of Lights in the Exodar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47224] = { id = 47224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vindicaar", description = "Everything is prepared for our assault. We need only establish the beacon to transport us to the vessel.\n\nOnce the beacon arrives, place your hand upon its surface to board the Vindicaar, the instrument of our retribution.", progress = "Today marks the beginning of the Legion's downfall.", completion = "I have waited many years for this day.\n\nBehold the triumph of the draenei, the Vindicaar!", objectives = "Board the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47226] = { id = 47226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Orphaned Hatchling", description = "<The surviving hatchling bleats piteously as it gazes at its mother's corpse.\n\nIt inspects you hopefully and seems to want to follow you.\n\nPerhaps you can find someone in Warbeast Kraal who can care for it?>", completion = "Are you de Hordemon I have been hearing so much about? I expected you to be a bit larger. Ha!\n\nHey! What do you have dere?", objectives = "Find someone in Warbeast Kraal who cares for young direhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47228] = { id = 47228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xibalan Ecology", description = "I had really hoped this area would be more hospitable.\n\nThe Zandalari have been no help whatsoever in clearing this space for archaeological exploration. Before we can even begin to uncover Xibala's secrets, we must make it safe for those less combat savvy to do their work.\n\nYou will find the ruins ahead infested with all manner of carnivorous beasts. The few intrepid explorers who ventured within have all failed to return.\n\nLocal ecology will not stand in the way of progress, {name}. Understand?", completion = "I hear this region is very supportive of such life. Their numbers will recover... elsewhere.", objectives = "Slay 8 Xibalan predators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47229] = { id = 47229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bulwark of Torcali", description = "We got Old Rotana up on her feet again. Load up an' take her reins.\n\nGive us some cover so Talanji can fight her way in from her side.", completion = "Thank you! Though we must not stay here. More blood trolls are coming. Where is my father?", objectives = "Ride Old Rotana into battle against the blood trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47235] = { id = 47235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrying for the Eye", description = "On behalf of the Horde we seek a relic called the Eye of Xibala.\n\nThe locals have been no help whatsoever and Miss Tae'shara insists that we use her survey equipment.\n\nI abhor guesswork. Instead we shall use a more direct method: scrying.\n\nI will mark three locations on your map. I would like you to place a scrying vessel at each of them. I will use their measurements to isolate the relic's location and we will be on our way.", completion = "Excellent work. Allow me to review the results and we will be on our way.", objectives = "Place 3 Scrying Vessels in Xibala.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47238] = { id = 47238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Seat of the Triumvirate", description = "Even with the Sigil of Awakening in hand, the Crown cannot save us until it is whole.\n\nThat is why we must enter the Seat of the Triumvirate, even knowing that L'ura awaits us there.\n\nThis is a dire task, one that I would not ask if it were not completely necessary.\n\nWe will descend together. Come.", progress = "Such a task I cannot undertake alone. Your help is greatly appreciated, {name}.", completion = "This is grave news indeed. It would be wise to follow Alleria's lead from here.", objectives = "Seek the Crest of Knowledge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47241] = { id = 47241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of Death", description = "We have four loa, but we only know where one is: Bwonsamdi.\n\nAs uncomfortable as it makes me, I am prepared to do anything to stop de blood trolls... even if it means dealing with de loa of death.\n\nAges ago, Bwonsamdi had a temple here in Nazmir. My scrying has revealed a few locations to de north where I sense a magical presence. Search dem for clues.\n\nHurry, {name}. Zuldazar will fall if we cannot obtain Bwonsamdi's help!", progress = "Having any luck in de search?", completion = "You are looking for Bwonsamdi's temple? You must be desperate to be going dere.\n\nLucky for you, I am headed dat way myself.", objectives = "Search for clues to the location of the loa, Bwonsamdi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47244] = { id = 47244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Culling of Souls", description = "Only two types enter Bwonsamdi's temple anymore: those looking to make a deal with death, and de dead. You do not stink, so I guess you are de former.\n\nI am headed to de temple myself, so how about a trade?\n\nSee de land across de bridge? Dere is a witch named Najima dat I have been tracking. De blood trolls are corrupt to de core, but their souls are useful as offerings to Bwonsamdi. She is too strong for me to deal with, but if you can slay her, I will take you to de temple.\n\nI give you my word.", completion = "Dis should do it. Her soul is perfect for an offering.\n\nNow, before we go to de temple, there is one more thing to do...", objectives = "Defeat Blood Witch Najima.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47245] = { id = 47245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting the Message", description = "Da loa be powerful, but we be needin' soldiers if we gonna have a chance of stopping dem blood trolls from building dat giant of theirs. If we not be able ta destroy dat thing before it be finished, den Zuldazar and all of our people gonna be dead!\n\nWe need da help of da Horde!\n\nWord of da situation already be sent to da warchief. As soon as we be hearin' her reply, we can mov-- \n\nWait... what be dat noise?", completion = "Goblins... of all da worthy units in da Horde, why da warchief have ta be sendin' us goblins?", objectives = "Investigate the disturbance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47246] = { id = 47246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remnants of the Damned", description = "Ever since da spirits have begun calling upon this \"G'huun\" me temple has been covered with the unbearable taint of the undead. \n\nDa undead be an abomination, but da bloodstones that create them be powerful. They could be of use ta Bwonsamdi.\n\nIf you wish ta show me your fervor, then cleanse me temple of their filth and bring me their bloodstones.", objectives = "Collect 6 Decaying Bloodstones for Bwonsamdi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47247] = { id = 47247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Which Haunts the Dead", description = "Bwonsamdi knows why ya be here. Ya be seekin' me favor.\n\n<Bwonsamdi ponders you silently.>\n\nA test, ta see if ya be worth Bwonsamdi's time.\n\nDere be spirits whose prayers sing of something called \"G'huun.\" Dey pay me homage no more. I will not allow da desecration of me own temple!\n\nGo and subdue da strongest of da ancient spirits.\n\nIf ya do dis for me, ya may be worth da trouble after all.", completion = "Ah, I feel their souls strengthening me powers. I knew ya be worth Bwonsamdi's time.", objectives = "Defeat Hex Priestess Tizeja and Warlord Malaja.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47248] = { id = 47248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "'Til Death Do Us Part", description = "I don't know who you are, but I need your help.\n\nMy precious Valjabu always told me he didn't care dat he took de vows of a priest... we would be together forever. \n\nWell, my time came to pass, and I knew I'd not be able to go on without him. I came back and have been waiting in dis spot for... it seems forever, and Valjabu never showed!\n\nI've been walking around dis world for far too long.\n\nPlease, I beg you, bring a memento of my Valjabu back to me!", progress = "Did you find Valjabu yet? His urn is around here somewhere.", completion = "<Salazae looks distraught.>\n\nOh! Valjabu... why did you go on without me?\n\n<A ghostly tear drops from her eye.>\n\nThank you, stranger. Now I can pass on with no regrets.", objectives = "Obtain Valjabu's Tusk Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47249] = { id = 47249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulbound", description = "Ya did well with me tasks. I be thinkin' ya show promise. Ya might be worthy of a deal.\n\nVery well, I pledge ta lend ya me powers ta use against ya foes. In exchange, ya be sendin' one million souls ta Bwonsamdi! No need ta look shocked, ya be plenty capable of doing dis.\n\nCome, meet with me at da Court of Spirits. Dere, we will finalize our agreement.", completion = "Dese blood trolls and their \"god\" G'huun, dey be far more of a threat than I realized. Da ritual ta seal da pact between ya and I be incomplete, but considerin' da circumstances, I tink we can skip da formalities.\n\nAs long as da price be paid, ya can count on Bwonsamdi's aid.", objectives = "Speak to Bwonsamdi in the Court of Spirits and complete the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47250] = { id = 47250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We'll Meet Again", description = "Now, it be time for ya ta leave. \n\nDere be many of dem blood troll souls for ya ta be sendin' to da Other Side for Bwonsamdi, and ya not gonna find any more of dem here.", completion = "So, you formed a pact with Bwonsamdi, too? Good, de more souls for Bwonsamdi, de stronger he is, and dat works out better for de both of us. Just leave some hunting for Hanzabu. I have my own pact to pay for!", objectives = "Travel to Zo'bal Ruins and speak with Hanzabu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47251] = { id = 47251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interesting Times", description = "{name}, I don't mean to alarm you, but we may be experiencing some... temporal disturbances.\n\nHave you ever heard the phrase 'I hope the past doesn't come back to haunt you?'\n\nCome visit me in the Valley of Spirits and we can speak more.", completion = "{name}, you're here. You must have received my letter.", objectives = "Meet with Historian Ju'Pa in the Valley of Spirits of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47252] = { id = 47252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Interesting Times", description = "{name}, I don't mean to alarm you, but we may be experiencing some... temporal disturbances.\n\nHave you ever heard the phrase 'I hope the past doesn't come back to haunt you?'\n\nCome visit me in the Stormwind Royal Library and we can speak more.", completion = "{name}, you're here. You must have received my letter.", objectives = "Meet with Historian Llore in the Royal Library of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47253] = { id = 47253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Originals", description = "Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism.\n\nI speak, of course, about Lord Kazzak, Azuregos, and the Dragons of Nightmare.\n\nLegends have it that so sought after were their treasures, that armies would camp overnight to hunt them down.\n\nWe have felt disturbances in the timeways, coincidentally located where these giants once roamed. \n\nWould you mind investigating for us? Strange things happen during this time of year.", progress = "They're just memories, right?", completion = "Let us use this moment to reflect upon the past, lest we forget the lessons it teaches us, and doom ourselves to repeat it once more.", objectives = "Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47254] = { id = 47254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Originals", description = "Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism.\n\nI speak, of course, about Lord Kazzak, Azuregos, and the Dragons of Nightmare.\n\nLegends have it that so sought after were their treasures, that armies would camp overnight to hunt them down.\n\nThe dragons have felt disturbances in the timeways, coincidentally located where these giants once roamed. \n\nThey have tasked me with finding champions to investigate.", progress = "They're just memories, right?", completion = "Let us use this moment to reflect upon the past, lest we forget the lessons it teaches us, and doom ourselves to repeat it once more.", objectives = "Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47255] = { id = 47255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47256] = { id = 47256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47257] = { id = 47257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bones of Xibala", description = "Far to the south you will find the bones of an ancient creature. This is Xibala, the progenitor, first of the devilsaurs. She was mother to Rezan, mother to all that came after. The Zandalari do not live there, as it belongs to beasts now.\n\nI have heard rumors of some of your Horde arriving in search of something among her bones.\n\nThis is ill advised. Look into it, won't you?", completion = "I've waited for such a find all my life. I will make my father proud.", objectives = "Travel to Xibala and speak with Examiner Tae'shara Bloodwatcher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47258] = { id = 47258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for a Siege", description = "It would seem we must make ready for a siege. For now, return to your Horde in Dazar'alor. Prepare for de coming conflict.\n\nShould de forces of Nazmir surge, I will send word.", completion = "Though our warchief may balk at further delays, I believe we are honor-bound to assist the Zandalari. \n\nThis is about more than gaining an ally in wartime. The Horde was founded on the idea of aiding those facing their hour of need.\n\nJust as Thrall once came to the defense of my people, so we must help save Zandalar.", objectives = "Speak with Baine Bloodhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47259] = { id = 47259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn Daycare", description = "Handler Bazkoji had a real gift with de little ones. If dis hatchling is following you, it must mean Bazkoji is dead.\n\nI don't have time to find another handler. Are you up to de task?\n\nIt's a lot of work, and de little ones get attached real fast. If you're going to care for it, it will be a commitment. That baby will be depending on you. I hope you will be up to de task of feeding and protecting it.\n\nFirst things first: food. Dere is plenty of fodder in de pens and river below.", completion = "Not bad. Dat baby is looking stronger already.", objectives = "Feed your hatchling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47260] = { id = 47260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Side Effects May Include...", description = "<Your direhorn companion hiccoughs repeatedly. Each time, it either shrinks or grows by a perceptible amount. It whines at you in distress. \n\nYou could use some help.>", completion = "I knew it was a bad idea to trust this small green mon.", objectives = "Speak to Beastlord L'kala in Warbeast Kraal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47261] = { id = 47261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Train Your Direhorn", description = "I have to get some of whatever you fed your baby! Wow!\n\nNow dat it's bigger, it is time to teach it to be a reliable battle companion.\n\nLet's see how it does against a tougher challenge, hmm?\n\nTalk to Kraal Master B'khor when you are ready to begin.", progress = "How did de training go?", completion = "Whoops. At least dat was quite entertaining to watch! Ha ha ha!\n\nI guess you two have earned your places here for sure!", objectives = "Talk to Kraal Master B'khor and choose to train your direhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47262] = { id = 47262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Blood Trolls", description = "De loa are smiling on us today. De \"matriarch\" of dese blood trolls, a sick monster named Ateena, is up ahead.\n\nWe have a change in plans, {name}. We will end dis threat now. We kill Ateena and de blood trolls will be thrown into chaos.\n\nShe is a powerful hexxer. Go start de fight and I will ambush and catch her off guard.\n\nLet us get moving. We will be back in Zuldazar before de day is over.", completion = "Ateena will not get away from us, we have to keep moving.", objectives = "Kill Ateena, the Matriarch of the blood trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47263] = { id = 47263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time of Revelation", description = "I can feel Ateena's dark voodoo up ahead. We need to stop whatever she is planning with dis \"G'huun\".\n\nBe ready for anything, {name}. We do not know what power Ateena truly has.\n\nI do know one thing. If G'huun is threatening my people, den it will die, just like Ateena.", completion = "De blood troll threat is bigger than I ever imagined. Dat construct is enough to destroy all of Zuldazar\n\nWe need more than de Horde to stop dis.", objectives = "Help Talanji chase down Ateena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47264] = { id = 47264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave None Standing", description = "Now you see what my father refuses to acknowledge. De blood trolls are slaughtering us, and dey need to be stopped.\n\nOur plan is simple, {name}. We will go out dere and kill as many of dese blood trolls as we can. You go east, I go north.\n\nMeet with me after and we will see what is left to do. We will teach dese blood trolls to fear de Zandalari!", completion = "Are you finished? Good, because we are close to ending dis menace.", objectives = "Slay 6 blood trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47272] = { id = 47272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhorn Growth Hormone", description = "Nice little critter you got there. Seems a tad too small to be much more than a nuisance though. \n\nWanna help a friend make a profit? There's an abundance of opportunity here, but these trolls won't listen to me!\n\nTell you what, I can make a supplement of sorts that'll make hair grow on your chest! Er, your hatchling's chest! \n\nI know direhorn are vegetarians and all, but there's a reason all the biggest predators eat meat!\n\nRapid growth requires protein. LOTS of protein.\n\nYou interested?", progress = "So? Did you get everything I need?", completion = "Meat is pretty miraculous stuff, you know!\n\nEr, you might want to keep the details about this to yourself for the time being.", objectives = "Collect 10 Steaming Fresh Carrion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47282] = { id = 47282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Aid Shop Searched" }
quests[47283] = { id = 47283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chop, Chop!", description = "Throm-ka, {name}.\n\nI'm always looking for someone who thinks they can swing an axe with the best of them.\n\nIf you can remove that sapling without much trouble, I'm sure we can find a better use for your skills.", progress = "Hmm?", completion = "Just the kind of strength we need around here.", objectives = "Pick up a Sturdy Axe, then gather 5 Freshly-Chopped Wood from the nearby Sapling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47287] = { id = 47287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vindicaar Matrix Core", description = "Much has happened on Argus that concerns me but none moreso than Xe'ra's fate. I wonder sometimes if we are doing the right thing? \n\nBut we must carry on. I can rig the Matrix Core that powers the Vindicaar to allow you to call on the power of our guns when you have need of them on the planet. \n\nGo to the Matrix Core in the room at the heart of our ship. Once linked, whatever powers the core has installed now and in the future will be at your disposal.", progress = "Have you linked Light's Judgment into the Vindicaar Matrix Core?", completion = "Light's Judgment will now fire on your command when you use the Matrix Uplink. \n\nPerhaps you will find more objects that we can link into the Matrix on your travels. I have routed enough energy to that part of the Core to handle anything that you can link into it. \n\nGo well, my friend.", objectives = "Link Light's Judgment into the Vindicaar Matrix Core.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47288] = { id = 47288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valuable Fossils" }
quests[47289] = { id = 47289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teddies and Tea", description = "There's nobody to play with here anymore. But you'll play with me, right <mister/lady>?\n\nIt's time for tea! Help me find the other guests, please!", progress = "This is going to be the best tea party ever!", completion = "Hooray! Only one more guest left to find.", objectives = "Gather Mr. Munchykins, Trunksy, and Mayor Striggs for the tea party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47290] = { id = 47290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "World Event Dungeon - Hummel" }
quests[47310] = { id = 47310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naptime", description = "Your not-so-little guy is looking a bit ragged after such an exciting day. I bet you both need a rest, hm?\n\nCome back later when you're a bit stronger.", progress = "I bet you and your direhorn need a bit of rest, hm?", completion = "I will look after your little one for de time being. Go on your adventures. Learn de ways of de Zandalari. When you are both ready, I will have an offer for you.", objectives = "Stable your direhorn in the Beast Pen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47311] = { id = 47311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Headbutting 101", description = "Your beast is looking well fed. Good. Try and keep it dat way.\n\nNow, next you need to teach your little one to defend itself. Direhorns in de wild are prey for much larger creatures and de young are easy pickings for saurid and their like.\n\nGo out into de Savagelands and show your little one how to fend dem off.\n\nIt's all in de horn, {name}.", completion = "I see a gleam of confidence in your hatchling's eyes. Good. It will need it.", objectives = "Assist your hatchling in fighting 12 creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47312] = { id = 47312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queenfeather", description = "Ah, so you are de one who inherited Bazkoji's herd. What is left of it, anyway.\n\nI know what killed him, and I tried to warn him. Queenfeather is a vicious ravasaur, bigger than de rest and smarter as well. Most of de eggs around here are hers.\n\nUsually I praise de strength of such a beast, but she has become a nuisance.\n\nYou will find her guarding her nests in de feeding grounds. Kill her and bring back one of her head feathers as proof dat de deed is done.", progress = "Does Queenfeather still stalk us?", completion = "Good. Now dat de bloodthirsty matriarch is gone, maybe we can plant one of ours back into de brood as a replacement... Hmmm.", objectives = "Slay Queenfeather and claim one of her feathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47313] = { id = 47313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discreet Discussions", description = "General Jakra'zet cannot be trusted. \n\nHe is up to something, but I do not know what.\n\nAny who question his actions earn demselves a trip to de sands. \n\nAs long as he remains in power, my city will never be safe.\n\nSpeak to his guards. See what you can find out, but be discreet. We do not want to alert Jakra'zet to our actions.", progress = "It is not safe to ask questions about de general around here.", completion = "You are going to make more enemies than allies asking questions like dat around here.", objectives = "Question Enforcers within Dazar'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47314] = { id = 47314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumors of Exile", description = "Talanji sent you, didn't she? \n\nDe princess needs to know dat it is no longer safe to ask such questions so openly. \n\nWarguard Rakera spoke out, and no one has heard from her since. \n\nRumor has it she was exiled to Vol'dun.", completion = "We will not let Rakera and whatever she knows be lost to de sands.", objectives = "Follow Bladeguard Kaja.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47315] = { id = 47315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Dunes", description = "Whatever Rakera uncovered, it was important enough to earn her a death sentence to de sands. \n\nWe must head into Vol'dun to find her. \n\nWe cannot let whatever she knows about Jakra'zet die with her in de dunes.", completion = "These snakemen will pay for what they've done to my home.", objectives = "Fly into the deserts of Vol'dun and search for Warguard Rakera.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47316] = { id = 47316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in the Sand", description = "I found this journal buried in the sand. \n\nKiro tried to toss it in the fire.\n\n\"Our wagon has no space for a diary, Meerah. What practical use does it have?\"\n\nDon't tell him I said so, but I think it's fascinating! Can you imagine what kinds of secrets it holds? \n\nQuite a few pages are missing, but I bet you can recover them out on the dunes!", progress = "What have you found?", completion = "Dis is Rakera's handwriting. I'd know it anywhere.", objectives = "Recover the journal's missing pages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47317] = { id = 47317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for Survivors", description = "It is good to see you are safe, but what of de others? Have dey been lost to de sands?\n\nYou need to head back to de crash site and see if de others survived.\n\nI will ask around and see if these fox people can tell us anything about Rakera.", completion = "Jorana knew de risks when she agreed to enter de sands, but I still can't help but feel responsible for her death.\n\nI can only hope dat Tarkaj somehow made his way to safety.", objectives = "Search for survivors near the crash site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47319] = { id = 47319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorative Venom", description = "Meerah here found your friend in the dunes. The lightning strike nearly killed her. It might still, without treatment. \n\nThe wasps within the grove have a painful sting, but their venom also has restorative properties. \n\nI can extract what I need from their glands.\n\nWith an ample amount of venom, we should be able to soothe your friend's wounds.", progress = "Have you brought the glands? We can't heal your friend without them.", completion = "<Kiro quickly inspects the glands.>\n\nThese should work well.", objectives = "Collect 15 Sandstinger Venom Glands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47320] = { id = 47320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Balm to Calm", description = "As promised, here is the balm that should remedy your companion's injuries. \n\nApply it liberally to any bits of exposed flesh.\n\nIts effects should be felt immediately.", completion = "Did these creatures come to our aid?\n\nDe last thing I remember, we were flying over de sethrak empire. There was a blinding flash of light before things went dark...", objectives = "Use the Restorative Balm on Bladeguard Kaja.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47321] = { id = 47321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knickknack Takeback", description = "Nisha told me you came here in search of an exile. One named Rakera? \n\nWe don't know her, but we might be able to help you find her. \n\nYou help us, and we help you. Deal?\n\nWe survive by scavenging. We trade what we find, but the sethrak that raided our burrows made away with many of our knickknacks.    \n\nI always knew they were ruthless, but never imagined they'd be so greedy.\n\nTake back what the sethrak have taken, and I'll see that you are provided safe passage through the dunes.", progress = "You help us, and we help you. Deal?", completion = "You're more resourceful than you look.", objectives = "Collect 6 Knickknacks from sethrak within The Serpent's Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47322] = { id = 47322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aided Escape", description = "The sethrak may be strong, but we're quick. Well, at least Mekaru and I are.\n\nWe just barely made it back to the wagon with our tails attached. \n\nThe others weren't so lucky, I guess. We've been waiting a while, and still no sign of them. \n\nIf you're headed into the thick of it, would you mind looking for our friends?", progress = "We abandoned our scavenging as soon as the sethrak showed up. Not all of us made it to safety...", completion = "Thanks, {name}. We owe you our lives.", objectives = "Free Hakasi and Kipp from within The Serpent's Maw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47324] = { id = 47324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlikely Allies", description = "I believe this is one of the Keepers' keys! Only Vorrik would know for sure. \n\nWe need to head to the temple at once. \n\nMy pterrordax can take us there when you're ready, but we need to hurry.", completion = "We cannot let the Faithless take this temple!", objectives = "Fly to the Sanctuary of the Devoted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47327] = { id = 47327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Answering Their Attacks", description = "The sethrak's attacks on our burrows cannot go unanswered. \n\nThey need to learn that not all within the desert will give up so easily. \n\nThe only thing the sethrak understand is blood, so that's the language we'll use to teach them.\n\n<Nisha pauses and looks at you, skeptical that you understood her.>\n\nI'm saying we need to kill the sethrak here. All of them.", progress = "The sethrak will answer for what they have done.", completion = "Their blood flows down the dunes back to their fortress. The sethrak will think twice before attacking our burrows again.", objectives = "Kill sethrak in the Abandoned Burrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47329] = { id = 47329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodwatcher Legacy", description = "Greetings, {name}.\n\nI have been sent on behalf of my father, High Examiner Tae'thelan Bloodwatcher, to oversee the extraction of all fossils, relics, and artifacts from this area.\n\nMy sources inform me that an object that could advance the Horde's cause may be buried beneath this very site.\n\nI will require your help extracting it. You see, these nightborne are not precisely good with their hands. Nor do they enjoy getting dirty.\n\nCould you be a dear and set a good example?", progress = "By all means, let us assist young Tae'shara. Such enthusiasm is to be rewarded.", completion = "You used your hands! How quaint. The nightborne have devised a number of ways to avoid such petty labors.", objectives = "Help Examiner Tae'shara Bloodwatcher recover a Xibalan fossil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47330] = { id = 47330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers of a Frightened World", description = "Champion, Magni needs your help!\n\nThe Speaker has a message for you, perhaps from Azeroth herself. He seems to be having trouble understanding her, but I'm sure he can explain everything better.\n\nHe said he was in Sholazar Basin, in Northrend. He should be contacting you shortly.", progress = "Yes, {name}? What news do you bring?", completion = "This warning is an ill omen indeed, {name}. It seems the fate of Azeroth is tied to that of Argus, the homeworld of the Legion.\n\nWe must uncover the Dark Titan's plan! I believe the Speaker's connection to the world soul will prove crucial to our efforts.\n\nStay vigilant, Huntmaster. We must trust in Magni's guidance... and Azeroth's as well.", objectives = "Meet Magni in Sholazar Basin and hear the warning.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[47331] = { id = 47331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[47332] = { id = 47332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Next Move", description = "Princess Talanji plans to travel north to Nazmir. The blood trolls there are a threat she believes her father refuses to acknowledge.\n\nGeneral Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe.\n\nYou will also need to win over King Rastakhan here in Zuldazar. This city is vast and has many secrets.", sourceObjective = "Choose your next move in Zandalar.", sourceObjectiveStatus = "unverified-source-field" }
